/**
 * Syntax tree of the FML subset generated by the FHIR Mapping Workbench.
 *
 * Contract: the generator builds ONLY these nodes and hands them to the printer (fml-print.ts).
 * Every construct here is covered by the checks (grammar mapping.g4 @8bb04b4,
 * HL7 engine org.hl7.fhir.core 7.0.5, Bundle validation). Adding a node = first adding
 * a golden test that covers it.
 *
 * Names are "branded types": they can only be obtained from the constructors at the end of the file,
 * which reject values not allowed by the grammar or by the HL7 parser.
 */

// ---------------------------------------------------------------- names
/** Group or map name: grammar token ID, ^[A-Za-z][A-Za-z0-9]*$ (no '_'). */
export type GroupName = string & { readonly __brand: 'GroupName' };
/** Variable, alias, parameter or element: token IDENTIFIER, ^[A-Za-z_][A-Za-z0-9_]*$. */
export type Identifier = string & { readonly __brand: 'Identifier' };
/** Rule name, printed between double quotes: ^[A-Za-z0-9_.-]+$ (e.g. R-006-1, Encounter0-id). */
export type RuleName = string & { readonly __brand: 'RuleName' };

// ---------------------------------------------------------------- map
export interface StructureMapAst {
  url: string;                 // canonical; printed between double quotes
  name: GroupName;             // printed between backticks: the only form accepted by both the grammar and the HL7 parser
  uses: Use[];
  groups: Group[];             // the first one is the table's main group
}

export interface Use {
  url: string;
  alias: Identifier;
  mode: 'source' | 'target' | 'produced';
}

export interface Group {
  name: GroupName;
  params: [Param, Param, ...Param[]];   // the grammar requires at least two parameters
  rules: Rule[];
  comment?: string;                     // comment line before the group
}

export interface Param {
  mode: 'source' | 'target';
  name: Identifier;
  type?: Identifier;
}

// ---------------------------------------------------------------- rules
export interface Rule {
  name: RuleName;
  comment?: string;            // printed as a // line before the rule (never /// : rejected by the HL7 parser)
  source: Source;              // always exactly one source
  targets: Target[];           // empty = rule without '->' (e.g. "src then Group(...)")
  then?: Then;
}

export interface Source {
  context: Identifier;         // e.g. src
  element?: Identifier;        // e.g. AdmissionDate → src.AdmissionDate
  alias?: Identifier;          // as v
  where?: Expr;                // where ( ... )
}

/** Element targets only: context.element [= transform] [as alias]. */
export interface Target {
  context: Identifier;
  element: Identifier;
  transform?: Transform;
  alias?: Identifier;
}

export type Transform =
  | { kind: 'literal'; value: string | number | boolean }                 // 'final', 3, true
  | { kind: 'copy'; variable: Identifier }                                // = v
  | { kind: 'create'; type: Identifier }                                  // create('Encounter')
  | { kind: 'c'; system: string; code: string; display?: string }         // Coding
  | { kind: 'cc'; system: string; code: string; display?: string }        // CodeableConcept
  | { kind: 'evaluate'; variable: Identifier; expression: Expr };         // evaluate(i, 'Patient/' + $this)

export type Then =
  | { kind: 'rules'; rules: Rule[] }                                      // then { ... }
  | { kind: 'invoke'; group: GroupName; args: [Identifier, ...Identifier[]] }; // then Group(a, b)

// ---------------------------------------------------------------- FHIRPath (structured subset)
export type Literal = string | number | boolean;

/**
 * Generated FHIRPath expressions. Columns are always printed with the "$this." prefix:
 * a name starting with a capital letter, at the start of an expression, would be read as a type.
 */
export type Expr =
  | { kind: 'exists'; column: Identifier }                                // $this.col.exists()
  | { kind: 'anyOf'; column: Identifier; values: [Literal, ...Literal[]] } // $this.col.where($this = a or ...).exists()
  | { kind: 'noneOf'; column: Identifier; values: [Literal, ...Literal[]] } // $this.col.where($this = a or ...).empty()
  | { kind: 'thisEquals'; value: Literal }                                // $this = 'v' (filter on the alias)
  | { kind: 'and' | 'or'; args: [Expr, Expr, ...Expr[]] }
  | { kind: 'not'; arg: Expr }                                            // (expr).not()
  | { kind: 'prefixThis'; prefix: string }                                // 'Patient/' + $this
  | { kind: 'raw'; text: string };                                        // D6, technical role only; checked by grammar and engine

// ---------------------------------------------------------------- checked constructors
const re = {
  group: /^[A-Za-z][A-Za-z0-9]*$/,
  ident: /^[A-Za-z_][A-Za-z0-9_]*$/,
  rule: /^[A-Za-z0-9_.-]+$/,
};
/**
 * Words the official grammar (mapping.g4 @8bb04b4) does NOT accept as an element or variable name.
 * Checked on 9 November 2026 against 16 reserved words: the others (source, target, group, first, last, check,
 * where, map, uses, alias, prefix, extends) are accepted by the grammar and the HL7 parser without delimiters.
 * Backticks are no way out: the HL7 parser keeps them in the element name.
 */
const reserved = new Set(['share', 'default', 'log', 'then']);

function check(kind: string, value: string, pattern: RegExp): void {
  if (!pattern.test(value)) throw new Error(`${kind} is not valid in FML: "${value}"`);
  if (reserved.has(value)) throw new Error(`${kind} is an FML reserved word: "${value}"`);
}
export const groupName = (s: string): GroupName => (check('Group name', s, re.group), s as GroupName);
export const ident = (s: string): Identifier => (check('Identifier', s, re.ident), s as Identifier);
export const ruleName = (s: string): RuleName => {
  if (!re.rule.test(s)) throw new Error(`Invalid rule name: "${s}"`);
  return s as RuleName;
};
